(() => {
  const KEY='promptMasterV2';
  const defaults={quality:'masterpiece, best quality, amazing quality, very aesthetic',quantity:'1girl, 1boy',interaction:'',camera:'Wide shot',environment:'an empty Disney-style castle',lighting:'',style:'2d animation, anime',order:'quality'};
  const makeChar=(i)=>({name:i===0?'Elsa':i===1?'Naruto':'Personagem '+(i+1),main:i===0?'The girl is Elsa. She is wearing her classic blue dress.':i===1?'The boy is Naruto. He is wearing his orange and black outfit.':'',appearance:'',clothes:'',lora:'',pose:'',action:'',expression:'',gesture:'',gaze:'',position:'',extra:'',detailed:false});
  let state=JSON.parse(localStorage.getItem(KEY)||'null')||{...defaults,characters:[makeChar(0),makeChar(1)],locked:[],order:'quality'};
  state.characters ||= [makeChar(0)];
  const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
  const esc=s=>(s||'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
  const blocks=()=>({quality:state.quality,quantity:state.quantity,characters:state.characters.map(c=>[c.main,c.appearance,c.clothes,c.lora,c.pose,c.action,c.expression,c.gesture,c.gaze,c.position,c.extra].filter(Boolean).join(', ')).filter(Boolean).join('\n\n'),interaction:state.interaction,camera:state.camera,environment:state.environment,lighting:state.lighting,style:state.style});
  const build=()=>{const b=blocks(), order=state.order==='identity'?['characters','quality','quantity','interaction','camera','environment','lighting','style']:state.order==='composition'?['quality','quantity','camera','environment','characters','interaction','lighting','style']:['quality','quantity','characters','interaction','camera','environment','lighting','style'];return order.map(k=>b[k]).filter(Boolean).join('\n\n').replace(/,\s*,/g,',').trim()};
  function mount(){const main=document.querySelector('.main');if(!main)return;main.innerHTML=`<div class="top"><div><div class="eyebrow">WAI-ILLUSTRIOUS XL</div><h1 class="title">Prompt Architect</h1><p class="subtitle">Editor híbrido: cole prompts completos ou detalhe cada bloco.</p></div><div class="actions"><button class="btn" id="v2Reset">Restaurar</button><button class="btn primary" id="v2Copy">Copiar prompt</button></div></div><div class="v2-layout"><section><div class="card v2-card"><div class="v2-head"><h2>Blocos do prompt</h2><select class="select" id="v2Order"><option value="quality">Qualidade primeiro</option><option value="identity">Identidade primeiro</option><option value="composition">Composição primeiro</option><option value="original">Preservar ordem original</option></select></div><div class="v2-grid"><label>Tags de qualidade<textarea data-field="quality">${esc(state.quality)}</textarea></label><label>Quantidade de personagens<textarea data-field="quantity">${esc(state.quantity)}</textarea></label></div></div><div class="card v2-card"><div class="v2-head"><h2>Personagens</h2><button class="btn" id="v2AddChar">＋ Personagem</button></div><div id="v2Chars"></div></div><div class="card v2-card"><h2>Interações entre personagens</h2><textarea class="wide" data-field="interaction" placeholder="Ações conjuntas, contato, relação espacial...">${esc(state.interaction)}</textarea></div><div class="card v2-card"><h2>Câmera e composição</h2><textarea class="wide" data-field="camera">${esc(state.camera)}</textarea></div><div class="v2-grid"><div class="card v2-card"><h2>Ambiente</h2><textarea class="wide" data-field="environment">${esc(state.environment)}</textarea></div><div class="card v2-card"><h2>Iluminação</h2><textarea class="wide" data-field="lighting">${esc(state.lighting)}</textarea></div></div><div class="card v2-card"><h2>Estilo e acabamento</h2><textarea class="wide" data-field="style">${esc(state.style)}</textarea></div></section><aside><div class="card v2-card"><div class="v2-head"><h2>Prévia final</h2><span class="muted" id="v2Count"></span></div><textarea id="v2Preview" readonly></textarea><button class="btn primary" id="v2Copy2" style="width:100%;margin-top:10px">Copiar prompt final</button></div><div class="card v2-card"><h2>Biblioteca visual</h2><p class="muted">Selecione um campo de personagem e toque em uma imagem para inserir a tag.</p><select class="select" id="v2Target"><option value="pose">Pose corporal</option><option value="expression">Expressão facial</option><option value="gesture">Gestos</option><option value="camera">Câmera e composição</option></select><div class="v2-library" id="v2Library">Carregando tags…</div></div></aside></div>`;bind();renderChars();renderPreview();loadLibrary();}
  function renderChars(){const box=document.querySelector('#v2Chars');box.innerHTML=state.characters.map((c,i)=>`<div class="v2-char"><div class="v2-head"><h3>${esc(c.name||'Personagem '+(i+1))}</h3><div><button class="btn" data-detail="${i}">${c.detailed?'Recolher':'Detalhar personagem'}</button>${state.characters.length>1?`<button class="btn" data-remove="${i}">×</button>`:''}</div></div><div class="v2-grid"><label>Nome<textarea data-char="${i}" data-k="name">${esc(c.name)}</textarea></label><label>Prompt principal<textarea data-char="${i}" data-k="main">${esc(c.main)}</textarea></label></div>${c.detailed?`<div class="v2-advanced"><div class="v2-grid">${['appearance','clothes','lora','pose','action','expression','gesture','gaze','position','extra'].map(k=>`<label>${({appearance:'Aparência',clothes:'Roupas',lora:'LoRA e trigger',pose:'Pose corporal',action:'Ação individual',expression:'Expressão facial',gesture:'Gestos',gaze:'Direção do olhar',position:'Posição na cena',extra:'Tags adicionais'})[k]}<textarea data-char="${i}" data-k="${k}">${esc(c[k])}</textarea>${['pose','expression','gesture'].includes(k)?`<button class="btn v2-lib" data-lib="${i}" data-k="${k}">Abrir biblioteca</button>`:''}</label>`).join('')}</div></div>`:''}</div>`).join('');box.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.characters[+b.dataset.detail].detailed=!state.characters[+b.dataset.detail].detailed;save();renderChars();renderPreview()});box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.characters.splice(+b.dataset.remove,1);save();renderChars();renderPreview()});box.querySelectorAll('[data-char]').forEach(x=>x.oninput=()=>{state.characters[+x.dataset.char][x.dataset.k]=x.value;save();renderPreview()});box.querySelectorAll('.v2-lib').forEach(b=>b.onclick=()=>{document.querySelector('#v2Target').value=b.dataset.k;document.querySelector('#v2Library').scrollIntoView({behavior:'smooth'})})}
  function bind(){document.querySelectorAll('[data-field]').forEach(x=>x.oninput=()=>{state[x.dataset.field]=x.value;save();renderPreview()});document.querySelector('#v2Order').value=state.order;document.querySelector('#v2Order').onchange=e=>{state.order=e.target.value;save();renderPreview()};document.querySelector('#v2AddChar').onclick=()=>{state.characters.push(makeChar(state.characters.length));state.quantity=state.characters.length+' characters';save();renderChars();renderPreview()};['v2Copy','v2Copy2'].forEach(id=>document.querySelector('#'+id).onclick=()=>navigator.clipboard.writeText(build())) ;document.querySelector('#v2Reset').onclick=()=>{state={...defaults,characters:[makeChar(0),makeChar(1)]};save();mount()}}
  function renderPreview(){const p=document.querySelector('#v2Preview');if(p){p.value=build();document.querySelector('#v2Count').textContent=build().length+' caracteres'}}
  async function loadLibrary(){const box=document.querySelector('#v2Library');try{const m=await fetch('tags/manifest.json').then(r=>r.json());const groups=[['Heads',m.heads],['Posture',m.posture],['Composition',m.composition],['Gestures',m.gestures]];box.innerHTML=groups.map(([n,fs])=>`<details><summary>${n} (${fs.length})</summary><div class="v2-tag-grid">${fs.slice(0,24).map(f=>`<button data-tag="${esc(f.replace(/\.png$/,''))}"><img src="tags/${n.toLowerCase()}/${encodeURIComponent(f)}"><small>${esc(f.replace(/\.png$/,''))}</small></button>`).join('')}</div></details>`).join('');box.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const t=b.dataset.tag, target=document.querySelector('#v2Target').value;let c=state.characters[0];if(['pose','expression','gesture'].includes(target))c[target]=c[target]?c[target]+', '+t:t;else state[target]=state[target]?state[target]+', '+t:t;save();renderChars();renderPreview()})}catch(e){box.textContent='Biblioteca indisponível neste modo local.'}}
  const style=document.createElement('style');style.textContent='.v2-layout{display:grid;grid-template-columns:minmax(560px,1fr) 390px;gap:18px}.v2-card{margin-bottom:18px}.v2-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.v2-head h2,.v2-head h3{margin:0}.v2-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.v2-grid label{color:#cbd3e6;font-size:12px}.v2-grid textarea,.v2-card textarea{display:block;width:100%;min-height:58px;margin-top:7px;background:#0f121b;color:#eef2fb;border:1px solid #30394d;border-radius:9px;padding:10px;resize:vertical}.v2-card textarea.wide{min-height:80px}.v2-char{border:1px solid #30384a;border-radius:12px;padding:14px;margin-top:12px}.v2-advanced{margin-top:12px;padding-top:12px;border-top:1px solid #30384a}.v2-lib{margin-top:6px;padding:6px 9px}.v2-library details{margin-top:8px;border:1px solid #30384a;border-radius:9px;padding:9px}.v2-library summary{cursor:pointer;color:#dde3f4}.v2-tag-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:9px}.v2-tag-grid button{background:#202638;border:1px solid #343d55;color:#fff;border-radius:7px;padding:3px;min-width:0}.v2-tag-grid img{width:100%;height:62px;object-fit:cover;border-radius:5px}.v2-tag-grid small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.v2-card h2{font-size:15px;margin:0 0 12px}@media(max-width:1000px){.v2-layout{grid-template-columns:1fr}.v2-grid{grid-template-columns:1fr}}';document.head.appendChild(style);mount();
})();
